"use client";

import React, { useState } from "react";
import { AlertTriangle } from "lucide-react";

export function AnalyticsAnomalyAlertCard() {
  const [dismissed, setDismissed] = useState(false);

  if (dismissed) return null;

  return (
    <div className="w-full max-w-sm bg-card/45 backdrop-blur-xl border border-rose-500/20 p-5 rounded-2xl shadow-xl select-none font-sans text-foreground">
      <div className="flex items-center justify-between mb-3">
        <div className="flex items-center gap-1.5">
          <AlertTriangle className="w-4 h-4 text-rose-400" />
          <span className="text-xs font-bold uppercase tracking-wider text-rose-400">Anomaly Warning</span>
        </div>
        <button 
          onClick={() => setDismissed(true)}
          className="text-[9px] uppercase font-bold text-muted-foreground/60 hover:text-foreground"
        >
          Dismiss
        </button>
      </div>

      <div className="space-y-3.5">
        <div className="p-3 rounded-xl bg-rose-500/5 border border-rose-500/10 text-xs">
          <p className="font-bold mb-1">Server response peak detected</p>
          <p className="text-[10px] text-muted-foreground/60 leading-normal">Response spikes at 1,420ms (Avg 120ms) inside customer checkout nodes.</p>
        </div>

        <div className="h-10 flex items-end justify-between gap-1 border-b border-white/[0.04] pt-2">
          <div className="w-full bg-rose-500/20 h-[10%]" />
          <div className="w-full bg-rose-500/20 h-[15%]" />
          <div className="w-full bg-rose-500/80 h-[95%]" />
          <div className="w-full bg-rose-500/40 h-[30%]" />
        </div>
      </div>
    </div>
  );
}
